    wire logic [3:0] n1_7 = r1_7[13] ? 4'd0 : ((r1_7 > 14'sd15) ? {4{1'b1}} : r1_7[3:0]);
    // layer 3: 3 neurons x 8 inputs, class scores (signed)
    wire logic signed [10:0] l2n0_w1 = 11'($signed({1'b0, n1_0})) <<< 6;
    wire logic signed [10:0] l2n0_w2 = 11'($signed({1'b0, n1_1})) <<< 6;
    wire logic signed [9:0] l2n0_w3 = 10'($signed({1'b0, n1_2})) <<< 5;
    wire logic signed [10:0] l2n0_w4 = 11'($signed({1'b0, n1_3})) <<< 6;
    wire logic signed [10:0] l2n0_w5 = 11'($signed({1'b0, n1_4})) <<< 6;
    wire logic signed [7:0] l2n0_w6 = 8'($signed({1'b0, n1_5})) <<< 3;
    wire logic signed [11:0] l2n0_w7 = 12'($signed({1'b0, n1_6})) <<< 7;
    wire logic signed [9:0] l2n0_w8 = 10'($signed({1'b0, n1_7})) <<< 5;
    wire logic signed [12:0] l2n0_w9 = 13'sd2234;
    wire logic signed [11:0] l2n0_w10 = 12'(l2n0_w1) + 12'(l2n0_w2);
    wire logic signed [10:0] l2n0_w11 = 11'(l2n0_w4) - 11'(l2n0_w3);
    wire logic signed [10:0] l2n0_w12 = 11'(l2n0_w5) - 11'(l2n0_w6);
    wire logic signed [11:0] l2n0_w13 = 12'(l2n0_w8) - 12'(l2n0_w7);
    wire logic signed [12:0] l2n0_w14 = 13'(l2n0_w10) + 13'(l2n0_w11);
    wire logic signed [11:0] l2n0_w15 = 12'(l2n0_w12) + 12'(l2n0_w13);
    wire logic signed [13:0] l2n0_w16 = 14'(l2n0_w14) + 14'(l2n0_w15);
    wire logic signed [13:0] l2n0_w17 = 14'(l2n0_w16) - 14'(l2n0_w9);
    wire logic signed [13:0] n2_0 = l2n0_w17;
    wire logic signed [10:0] l2n1_w1 = 11'($signed({1'b0, n1_0})) <<< 6;
    wire logic signed [10:0] l2n1_w2 = 11'($signed({1'b0, n1_1})) <<< 6;
    wire logic signed [9:0] l2n1_w3 = 10'($signed({1'b0, n1_2})) <<< 5;
    wire logic signed [10:0] l2n1_w4 = 11'($signed({1'b0, n1_3})) <<< 6;
    wire logic signed [9:0] l2n1_w5 = 10'($signed({1'b0, n1_4})) <<< 5;
    wire logic signed [10:0] l2n1_w6 = 11'($signed({1'b0, n1_5})) <<< 6;
    wire logic signed [10:0] l2n1_w7 = 11'($signed({1'b0, n1_6})) <<< 6;
    wire logic signed [10:0] l2n1_w8 = 11'($signed({1'b0, n1_7})) <<< 6;
    wire logic signed [11:0] l2n1_w9 = 12'sd1582;
    wire logic signed [11:0] l2n1_w10 = 12'(l2n1_w1) + 12'(l2n1_w2);
    wire logic signed [10:0] l2n1_w11 = 11'(l2n1_w4) - 11'(l2n1_w3);
    wire logic signed [11:0] l2n1_w12 = 12'(l2n1_w5) + 12'(l2n1_w6);
    wire logic signed [11:0] l2n1_w13 = 12'(l2n1_w7) + 12'(l2n1_w8);
    wire logic signed [12:0] l2n1_w14 = 13'(l2n1_w11) - 13'(l2n1_w10);
    wire logic signed [12:0] l2n1_w15 = 13'(l2n1_w12) + 13'(l2n1_w13);
    wire logic signed [13:0] l2n1_w16 = 14'(l2n1_w14) + 14'(l2n1_w15);
    wire logic signed [12:0] l2n1_w17 = 13'(l2n1_w16) - 13'(l2n1_w9);
    wire logic signed [12:0] n2_1 = l2n1_w17;
    wire logic signed [11:0] l2n2_w1 = 12'($signed({1'b0, n1_0})) <<< 7;
    wire logic signed [8:0] l2n2_w2 = 9'($signed({1'b0, n1_1})) <<< 4;
    wire logic signed [11:0] l2n2_w3 = 12'($signed({1'b0, n1_2})) <<< 7;
    wire logic signed [11:0] l2n2_w4 = 12'($signed({1'b0, n1_3})) <<< 7;
    wire logic signed [11:0] l2n2_w5 = 12'($signed({1'b0, n1_4})) <<< 7;
    wire logic signed [9:0] l2n2_w6 = 10'($signed({1'b0, n1_5})) <<< 5;
    wire logic signed [10:0] l2n2_w7 = 11'($signed({1'b0, n1_6})) <<< 6;
    wire logic signed [11:0] l2n2_w8 = 12'($signed({1'b0, n1_7})) <<< 7;
    wire logic signed [11:0] l2n2_w9 = 12'sd1749;
    wire logic signed [11:0] l2n2_w10 = 12'(l2n2_w2) - 12'(l2n2_w1);
    wire logic signed [11:0] l2n2_w11 = 12'(l2n2_w3) - 12'(l2n2_w4);
    wire logic signed [12:0] l2n2_w12 = 13'(l2n2_w5) + 13'(l2n2_w6);
    wire logic signed [11:0] l2n2_w13 = 12'(l2n2_w7) - 12'(l2n2_w8);
    wire logic signed [12:0] l2n2_w14 = 13'(l2n2_w10) + 13'(l2n2_w11);
    wire logic signed [13:0] l2n2_w15 = 14'(l2n2_w13) - 14'(l2n2_w12);
    wire logic signed [13:0] l2n2_w16 = 14'(l2n2_w14) + 14'(l2n2_w15);
    wire logic signed [13:0] l2n2_w17 = 14'(l2n2_w16) + 14'(l2n2_w9);
    wire logic signed [13:0] n2_2 = l2n2_w17;
    // class scores and argmax, ties to the lowest class index
    wire logic signed [13:0] s0 = 14'(n2_0);
    wire logic signed [13:0] s1 = 14'(n2_1);
    wire logic signed [13:0] s2 = 14'(n2_2);
    wire logic       ge10 = s1 > s0;
    wire logic signed [13:0] m01 = ge10 ? s1 : s0;
    wire logic [1:0] c01 = ge10 ? 2'd1 : 2'd0;
    wire logic [1:0] cls = (s2 > m01) ? 2'd2 : c01;
    logic [LATENCY-1:0] vpipe;
    always_ff @(posedge clk) begin
        out_cls <= cls;
        if (rst) vpipe <= '0; else vpipe <= in_v;
    end
    assign out_v = vpipe[LATENCY-1];
endmodule
`default_nettype wire
